def parse_cli_args():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--detector', choices=['pretrained', 'scratch', 'ensemble'], default='pretrained',
                   help='Detector model: pretrained (default selected submission), scratch (non-pretrained 1500ep), or ensemble (2-model)')
    p.add_argument('--det-threshold', type=float, default=0.3,
                   help='Detection threshold (default: 0.30, or 0.28 as analyzed in writeup)')
    p.add_argument('--movies', nargs='*', default=None,
                   help='Optional subset of video stems to run (e.g. 44b6_0113de3b)')
    p.add_argument('--max-frames', type=int, default=None,
                   help='Optional max frames per video for fast testing (default: None = full video)')
    p.add_argument('--workers', type=int, default=None,
                   help='Number of division/ILP worker processes (default: 1 locally, 4 on Kaggle)')
    p.add_argument('--setup-only', action='store_true',
                   help='Only materialize runtime scripts and models into working/ without running inference')
    args, _ = p.parse_known_args()
    return args

