(ADDON/'runtime'/'division_new_transfer.py').write_text('from pathlib import Path\nimport sys,json,pickle,collections,importlib.util,os\nimport numpy as np,torch,lightgbm as lgb\nW=Path(__file__).resolve().parent;sys.path[:0]=[str(W/\'legacy\'),str(W)]\nfrom parent import ParentScorer,VideoCrops,peaks_from_rows,make_image,save,SPACING_ZYX\nfrom choice_features import features as original_features\nfrom choice_net import Net\nfrom biohub_division_physical_pair_cpu import Candidate,PointClouds,PhysicalFeatureBuilder\nfrom biohub_division_pair_inference_oof import enumerate_candidate_pairs\nfrom types import SimpleNamespace\nsp=importlib.util.spec_from_file_location(\'addition_features\',W/\'addition_features.py\');af=importlib.util.module_from_spec(sp);sp.loader.exec_module(af)\nR=Path(os.environ[\'BIOHUB_ROOT\']);E=Path(os.environ[\'BIOHUB_CHOICE_OUT\'])\ndef main():\n scorer=ParentScorer(\'cuda\');scorer.models=scorer.models[:1];model=scorer.models[0]\n cp=torch.load(R/\'models/nn_h.pt\',map_location=\'cpu\',weights_only=False);net=Net(len(cp[\'mean\']));net.load_state_dict(cp[\'state\']);net.eval()\n old=torch.load(Path(os.environ[\'BIOHUB_CHOICE_MODEL\']),map_location=\'cpu\',weights_only=False);names=old[\'features\']\n treepath=R/\'models/lgb_hl\';tree=lgb.Booster(model_file=str(treepath/\'model.txt\'));norm=json.loads((treepath/\'normalization.json\').read_text());mu=np.asarray(norm[\'mean\']);sd=np.asarray(norm[\'std\']);assert len(mu)==93\n receipts=[]\n for v in [dict(stem=stem,base=str(E),source=str(E)) for stem in (E/\'config/one.txt\').read_text().split()]:\n  stem=v[\'stem\'];base=Path(v[\'base\']);source=Path(v[\'source\']);done=E/f\'new_division_checks/{stem}.json\'\n  if done.exists():receipts.append(json.loads(done.read_text()));continue\n  data=pickle.loads((base/f\'candidates/{stem}.pkl\').read_bytes());rows=data[\'node_rows\'];edges=data[\'edges\'];oldterms=json.loads((source/f\'transfer/choice/{stem}.json\').read_text());assert oldterms[\'candidate_contract\']==data[\'contract\'];groups=collections.defaultdict(list)\n  for x in oldterms[\'rows\']:groups[x[\'node_index\']].append(x)\n  clouds=collections.defaultdict(list);indices=collections.defaultdict(list)\n  for i,r in enumerate(rows):key=f\'{stem}_t{int(r["t"]):03d}\';clouds[key].append([r[a] for a in \'zyx\']+[r[\'node_score\']]);indices[key].append(i)\n  cloud={k:np.asarray(x) for k,x in clouds.items()};vox={k:x[:,:3] for k,x in cloud.items()};points={k:x*SPACING_ZYX for k,x in vox.items()};scores={k:x[:,3] for k,x in cloud.items()};builder=PhysicalFeatureBuilder(PointClouds(points,scores,{k:np.zeros(len(x),np.int8) for k,x in points.items()}),15.,6)\n  crops=VideoCrops(Path(os.environ[\'BIOHUB_DATA_DIR\'])/f\'{stem}.zarr\',peaks_from_rows(stem,rows));out={\'nn_h\':[],\'lgb_hl\':[]};audit=[]\n  for i,terms in sorted(groups.items(),key=lambda item:rows[item[0]][\'t\']):\n   r=rows[i];t=int(r[\'t\']);center=np.array([r[a] for a in \'zyx\']);case=f\'{stem}_t{t:03d}\';pi=indices[case].index(i);raw,heat=crops.inputs(t,center);im=make_image(raw,heat,np.zeros(3),np.zeros(3),scorer.mean,scorer.std)[None].cuda()\n   with torch.inference_mode(),torch.autocast(\'cuda\',dtype=torch.bfloat16,enabled=os.environ.get(\'BIOHUB_TH_AUX_AMP\',\'fp32\')==\'bf16\'):pred=model(im)\n   vals={k:x.float().cpu().numpy()[0].tolist() for k,x in pred.items()};h=float(vals[\'binary\']);flow=crops.flow.estimate(case,f\'{stem}_t{t+1:03d}\',center*SPACING_ZYX,\'source\')[1]\n   c=Candidate(str(i),\'detector\',\'2\',case,stem,t,3,points[case][pi],0,\'unknown\',\'unknown\');pairs,_=enumerate_candidate_pairs(c,0.,builder,vox,SimpleNamespace(parent_match_um=.25,max_pair_points=6,pair_radius_um=15.,fold=2));lookup={tuple(sorted([indices[f\'{stem}_t{t+1:03d}\'][p[k]] for k in [\'first\',\'second\']])):p for p in pairs}\n   fs=[];opts=[]\n   for term in terms:\n    p=lookup[tuple(sorted(term[\'children\']))];fs.append(original_features(p,points[case],points[f\'{stem}_t{t+1:03d}\'],pi,builder,stem,t,scores[case][pi]));opts.append(dict(daughter1_zyx=[rows[term[\'children\'][0]][a] for a in \'zyx\'],daughter2_zyx=[rows[term[\'children\'][1]][a] for a in \'zyx\']))\n   x=np.array([[f[k] for k in names] for f in fs],np.float32);q=dict(outputs=vals,next_flow_um=np.asarray(flow).tolist());ev=dict(parent_zyx=center.tolist(),options=opts);extra=af.extra(ev,q);xx=np.column_stack([x,np.full(len(x),h,dtype=np.float32)])\n   with torch.no_grad():nnscore=net(torch.tensor(np.clip((xx-cp[\'mean\'])/cp[\'std\'],-10,10),dtype=torch.float32)).flatten().numpy()\n   z=np.clip((np.column_stack([x,extra])-mu)/sd,-10,10);null=np.r_[z.mean(0),1.][None];allz=np.vstack([null,np.column_stack([z,np.zeros(len(z))])]);ss=tree.predict(allz,raw_score=True);delta=ss[1:]-ss[0]\n   assert np.isfinite(nnscore).all() and np.isfinite(delta).all()\n   for arm,sscore in [(\'nn_h\',nnscore),(\'lgb_hl\',delta)]:\n    for term,s in zip(terms,sscore):out[arm].append(dict(node_index=i,children=term[\'children\'],parent_t=t,parent_zyx=center.tolist(),logit=float(s),reward=float(-.2*np.tanh(s))))\n   audit.append(dict(node_index=i,th_logit=h,options=len(terms),null_lgb_score=float(ss[0])))\n  for arm,rr in out.items():save(E/f\'transfer/{arm}/{stem}.json\',dict(stem=stem,rows=rr,labels_read=False,candidate_contract=data[\'contract\'],strength=.2,policy=\'Same incumbent parents and valid pairs as originalchoice; LGB score minus learnt null.\'))\n  receipt=dict(stem=stem,parents=len(groups),options=len(oldterms[\'rows\']),coverage_equal=all(len(rr)==len(oldterms[\'rows\']) for rr in out.values()),th_seed=20260817,precision=os.environ.get(\'BIOHUB_TH_AUX_AMP\',\'fp32\'),research_precision=\'bf16; target numerical parity pending\',labels_read=False);assert receipt[\'coverage_equal\'];save(done,receipt);save(E/f\'outputs/th/{stem}.json\',audit);receipts.append(receipt);print(receipt,flush=True)\n save(E/\'checks/transfer_summary.json\',receipts);(E/\'TRANSFER_DONE\').touch()\nif __name__==\'__main__\':main()\n')
(ADDON/'runtime'/'addition_features.py').write_text('"""Candidate-specific TH alignment; label-free, daughter permutation invariant."""\nimport numpy as np\nSCALE=np.array([1.625,.40625,.40625])\ndef extra(e,q):\n out=q[\'outputs\'];offset=np.asarray(out[\'offset\'],float).reshape(2,3)*10\n count=np.asarray(out[\'count\'],float);count=np.exp(count-count.max());count/=count.sum()\n parent=np.asarray(e[\'parent_zyx\']);flow=np.asarray(q[\'next_flow_um\'])\n children=np.array([[o[\'daughter1_zyx\'],o[\'daughter2_zyx\']] for o in e[\'options\']]);actual=(children-parent)*SCALE-flow\n dist=np.linalg.norm(offset[None,:,None,:]-actual[:,None,:,:],axis=-1)\n assignments=np.stack([np.stack([dist[:,0,0],dist[:,1,1]],1),np.stack([dist[:,0,1],dist[:,1,0]],1)],1);best=assignments[np.arange(len(children)),assignments.sum(2).argmin(1)]\n # One-successor fit uses either slot; useful evidence, not a learned disappearance model.\n single=dist.min((1,2));best_single=float(single.min());sep=np.abs(np.linalg.norm(actual[:,0]-actual[:,1],axis=1)-np.linalg.norm(offset[0]-offset[1]));mid=np.linalg.norm(actual.mean(1)-offset.mean(0),axis=1)\n h=float(out[\'binary\']);mat=np.column_stack([np.full(len(children),h),np.tile(count,(len(children),1)),best.min(1),best.max(1),best.mean(1),mid,sep,single,np.full(len(children),best_single),best.mean(1)-best_single]);assert np.isfinite(mat).all()\n return mat.astype(np.float32)\nNAMES=[\'TH_logit\',\'count0\',\'count1\',\'count2\',\'slot_residual_min\',\'slot_residual_max\',\'slot_residual_mean\',\'midpoint_residual\',\'separation_residual\',\'single_successor_fit\',\'best_continuation_fit\',\'pair_minus_best_continuation_fit\']\n')
(ADDON/'runtime'/'choice_worker.py').write_text('"""D4 detector and exact structural-gated parent/ILP pipeline, one GPU shard."""\nimport argparse,json,os,pickle,subprocess,sys,time,traceback,collections\nfrom pathlib import Path\n\ndef main(a):\n started=time.perf_counter();b=a.addon/\'runtime\';out=a.out;out.mkdir(parents=True,exist_ok=True)\n cfg=json.loads(a.config.read_text());solver_cfg=cfg[\'solver\']\n assert cfg[\'parent_amp\']==\'fp32\' and solver_cfg[\'fusion\']==\'pair\'\n assert solver_cfg.get(\'pair_bonus\',0)>=0 and solver_cfg[\'pair_parent_threshold\']>=.1\n env=dict(os.environ,BIOHUB_ROOT=str(a.addon),BIOHUB_DATA_DIR=str(a.data),BIOHUB_PARENT_AMP=\'fp32\',BIOHUB_CANDIDATE_DIR=str(out/\'candidates\'),PYTHONDONTWRITEBYTECODE=\'1\',OMP_NUM_THREADS=\'1\',OPENBLAS_NUM_THREADS=\'1\',POLARS_MAX_THREADS=\'1\')\n env[\'PYTHONPATH\']=os.pathsep.join([str(b/\'vendor\'),str(b),env.get(\'PYTHONPATH\',\'\')]);os.environ.update(env);sys.path[:0]=[str(b/\'vendor\'),str(b)]\n stems=[p.stem for p in sorted(a.data.glob(\'*.zarr\'))][a.shard::a.shards];assert stems\n (out/\'config\').mkdir(exist_ok=True);(out/\'candidates\').mkdir(exist_ok=True)\n solver=out/\'config/solver.json\';solver.write_text(json.dumps(solver_cfg));post=out/\'config/post.json\';post.write_text(json.dumps(cfg[\'post\']))\n detector=[sys.executable,str(b/\'capture.py\'),\'--model-dir\',str(a.model),\'--test-dir\',str(a.data),\'--output-dir\',str(out/\'detector\'),\'--fold\',\'0\',\'--checkpoint\',\'checkpoint_final.pth\',\'--device\',\'cuda\',\'--amp\',\'fp16\',\'--detector-tta-mode\',\'d4-detector\',\'--det-threshold\',\'.3\',\'--division-weight\',\'.3\',\'--num-shards\',str(a.shards),\'--shard-index\',str(a.shard)]\n if a.max_frames is not None:detector+=[\'--max-frames\',str(a.max_frames)]\n process=None;log=None\n try:\n  if a.candidate_source:\n   for stem in stems:(out/\'candidates\'/(stem+\'.pkl\')).symlink_to(a.candidate_source/(stem+\'.pkl\'))\n  else:\n   log=(out/\'detector.log\').open(\'w\');process=subprocess.Popen(detector,env=env,stdout=log,stderr=subprocess.STDOUT)\n   if a.no_overlap:\n    if process.wait():raise RuntimeError(\'Detector failed; inspect detector.log\')\n  # Persistent frozen models share the GPU only with this shard\'s detector.\n  from parent import ParentScorer,score_video,save\n  import torch\n  scorer=ParentScorer();videos=[]\n  for stem in stems:\n   vstart=time.perf_counter();candidate=out/\'candidates\'/(stem+\'.pkl\')\n   while not candidate.exists():\n    if process and process.poll() is not None:raise RuntimeError(f\'Detector ended without candidate {stem}\')\n    time.sleep(.2)\n   candidate_ready=time.perf_counter();payload=pickle.loads(candidate.read_bytes());rows=payload[\'node_rows\'];outgoing=collections.Counter(s for s,t in payload[\'edges\']);eligible=[i for i in range(len(rows)) if outgoing.get(i,0)>=2]\n   parent=out/\'parent_scores\'/(stem+\'.json\');score_video(scorer,stem,rows,a.data,parent,eligible_indices=eligible if a.gate==\'fork\' else None)\n   parent_seconds=time.perf_counter()-candidate_ready\n   pairs=out/\'pair_scores_min01\'/(stem+\'.json\');one=out/\'config/one.txt\';one.write_text(stem+\'\\n\')\n   t=time.perf_counter()\n   if solver_cfg.get(\'pair_bonus\',0):\n    import pairs as pairs_module\n    pairs_module.run(out,\'one\',2)\n   else:save(pairs,dict(stem=stem,rows=[],reason=\'pair_bonus zero; pair scores unused in objective\',labels_read_at_inference=False))\n   pair_seconds=time.perf_counter()-t\n   env[\'BIOHUB_SOLVER_RECEIPTS\']=str(out/\'solver_dispatch\'/stem)\n   def command(label,args):\n    t=time.perf_counter()\n    with (out/(label+\'.log\')).open(\'w\') as f:subprocess.run([sys.executable,*map(str,args)],env=env,stdout=f,stderr=subprocess.STDOUT,check=True)\n    return time.perf_counter()-t\n   solve_seconds=command(\'solve_\'+stem,[b/\'biohub_fast_ilp.py\',b/\'solve_fusion.py\',\'--candidate\',candidate,\'--parent\',parent,\'--pairs\',pairs,\'--config\',solver,\'--output\',out/\'pair_graphs\'/(stem+\'.geff\'),\'--receipt\',out/\'solver_receipts\'/(stem+\'.json\')])\n   post_seconds=command(\'post_\'+stem,[b/\'post.py\',\'--source\',out/\'pair_graphs\',\'--dest\',out/\'pair_final\',\'--stems\',one,\'--data\',a.data,\'--config\',post])\n   env.update(BIOHUB_CHOICE_OUT=str(out),BIOHUB_CHOICE_BASE=str(out),BIOHUB_CHOICE_ARM=cfg[\'arm\'],BIOHUB_CHOICE_MODEL=str(a.addon/\'models\'/(\'learned_\'+cfg[\'arm\']+\'.pt\')))\n   choice_seconds=command(\'choice_transfer_\'+stem,[b/\'choice_transfer.py\'])\n   choice_seconds+=command(\'new_division_transfer_\'+stem,[b/\'division_new_transfer.py\'])\n   learned=dict(solver_cfg,learned_terms=str(out/\'transfer\'/\'nn_h\'/(stem+\'.json\')))\n   learned_cfg=out/\'config\'/(\'learned_\'+stem+\'.json\');learned_cfg.write_text(json.dumps(learned))\n   learned_seconds=command(\'choice_solve_\'+stem,[b/\'biohub_fast_ilp.py\',b/\'solve_choice.py\',\'--candidate\',candidate,\'--parent\',parent,\'--pairs\',pairs,\'--config\',learned_cfg,\'--output\',out/\'graphs\'/(stem+\'.geff\'),\'--receipt\',out/\'learned_solver_receipts\'/(stem+\'.json\')])\n   post_seconds+=command(\'choice_post_\'+stem,[b/\'post.py\',\'--source\',out/\'graphs\',\'--dest\',out/\'final_graphs\',\'--stems\',one,\'--data\',a.data,\'--config\',post])\n   videos.append(dict(stem=stem,total_nodes=len(rows),fork_capable_nodes=len(eligible),candidate_wait_seconds=candidate_ready-vstart,parent_seconds=parent_seconds,pair_seconds=pair_seconds,choice_seconds=choice_seconds,learned_seconds=learned_seconds,solve_seconds=solve_seconds,post_seconds=post_seconds,finished_at_seconds=time.perf_counter()-started))\n   save(out/\'pipeline_progress.json\',dict(videos=videos,elapsed_seconds=time.perf_counter()-started));print(json.dumps(videos[-1]),flush=True)\n  if process and process.wait():raise RuntimeError(\'Detector failed at final wait\')\n  report=dict(passed=True,stems=stems,videos=videos,elapsed_seconds=time.perf_counter()-started,config=cfg,gate=a.gate,pipeline_overlap=not a.no_overlap,candidate_reused=bool(a.candidate_source),parent_gpu_peak_bytes=torch.cuda.max_memory_allocated(),tracking_fallback=False)\n  if not a.candidate_source:report[\'detector\']=json.loads((out/\'detector\'/f\'summary_shard_{a.shard}.json\').read_text())\n  save(out/\'worker_receipt.json\',report);print(json.dumps(report),flush=True)\n except Exception:\n  (out/\'FAILED\').write_text(traceback.format_exc());raise\n finally:\n  if process and process.poll() is None:process.terminate();process.wait(timeout=30)\n  if log:log.close()\nif __name__==\'__main__\':\n p=argparse.ArgumentParser();p.add_argument(\'--addon\',type=Path,required=True);p.add_argument(\'--model\',type=Path,required=True);p.add_argument(\'--data\',type=Path,required=True);p.add_argument(\'--out\',type=Path,required=True);p.add_argument(\'--config\',type=Path,required=True);p.add_argument(\'--shard\',type=int,default=0);p.add_argument(\'--shards\',type=int,default=1);p.add_argument(\'--max-frames\',type=int);p.add_argument(\'--no-overlap\',action=\'store_true\');p.add_argument(\'--candidate-source\',type=Path);p.add_argument(\'--gate\',choices=[\'all\',\'fork\'],default=\'fork\');main(p.parse_args())\n')

