(ADDON/'runtime'/'final_post.py').write_text('"""Only final choice graph postprocessing changes; first-stage hypotheses stay frozen."""\nimport argparse,json,pickle,sys,time\nfrom pathlib import Path\nfrom collections import defaultdict\nimport zarr\nsys.path.insert(0,str(Path(__file__).parent/\'legacy\'))\nimport postbest as b\nimport structure_extra, first_projection\nimport boundary_mean1_post\n\ndef run(source,dest,stems,data,candidates,supported,normal_first=False):\n    assert not (supported and normal_first)\n    settings=dict(GAP_CLOSE_UM=4.5,GAP_REUSE_UM=3.2,GAP_MAX_ADDED_FRAC=.02,GAP_MAX_ADDED_ABS=2000,MIN_TRACK_LEN=9,MIN_TRACK_LEN_BY_DATASET={},LINEFIT_WINDOW=4,LINEFIT_WEIGHT=.6,LINEFIT_CAP_UM=2.,LINEFIT_HUBER_DELTA_UM=1.5)\n    for k,v in settings.items():setattr(b,k,v)\n    b.linefit=lambda n,e,stats:b.safer_local_linefit(n,e,stats,robust=False,cap_um=2.)\n    dest.mkdir(parents=True,exist_ok=True)\n    for stem in stems:\n        old=dest/f\'{stem}.post.json\'\n        if old.exists() and (dest/f\'{stem}.geff\').exists():\n            receipt=json.loads(old.read_text());assert receipt[\'settings\']==settings and receipt[\'supported_first\']==supported and receipt.get(\'normal_first\',False)==normal_first\n            continue\n        start=time.perf_counter();raw,re=b.read_graph(source/f\'{stem}.geff\')\n        final,fe,stats=b.apply_arm(\'gap_short_track_linefit\',raw,re,stem,data)\n        assert not supported\n        final,fe=boundary_mean1_post.apply(raw,re,final,fe,stem,data,candidates,b,stats)\n        extra={}\n        if supported:\n            payload=pickle.loads((candidates/f\'{stem}.pkl\').read_bytes());rows=payload[\'node_rows\'];edges=payload[\'edges\']\n            # apply_arm copies input; ensure native graph coordinates are still aligned.\n            assert all(all(float(n[k])==float(rows[i][k]) for k in (\'t\',\'z\',\'y\',\'x\')) for i,n in raw.items())\n            frame_max=max(int(r[\'t\']) for r in rows)\n            freezes=first_projection.image_freezes(zarr.open_group(str(data/f\'{stem}.zarr\'),mode=\'r\')[\'0\'],range(frame_max))\n            ctx=dict(raw=raw,re=re,final=final,fe=fe,rows=rows,candidates=edges,b=b,stem=stem,data_dir=data,freeze=set(freezes),first_projection=first_projection)\n            final,fe,extra=structure_extra.apply(\'x9_first_supported_anchor\',ctx)\n            b.validate_and_clip_graph(final,fe,stem,data,defaultdict(int))\n        if normal_first:\n            transitions={int(final[e[\'source_id\']][\'t\']) for e in fe if int(final[e[\'target_id\']][\'t\'])==int(final[e[\'source_id\']][\'t\'])+1}\n            freezes=first_projection.image_freezes(zarr.open_group(str(data/f\'{stem}.zarr\'),mode=\'r\')[\'0\'],transitions)\n            final,extra=first_projection.project(final,fe,set(raw),freezes)\n            extra[\'frozen_transitions\']=freezes\n            b.validate_and_clip_graph(final,fe,stem,data,defaultdict(int))\n        b.write_graph(dest/f\'{stem}.geff\',final,fe)\n        (dest/f\'{stem}.post.json\').write_text(json.dumps(dict(settings=settings,supported_first=supported,normal_first=normal_first,stats=stats,extra=extra,nodes=len(final),edges=len(fe),seconds=time.perf_counter()-start),indent=2))\nif __name__==\'__main__\':\n    p=argparse.ArgumentParser()\n    for name in [\'source\',\'dest\',\'stems\',\'data\',\'candidates\']:p.add_argument(\'--\'+name,type=Path,required=True)\n    g=p.add_mutually_exclusive_group();g.add_argument(\'--supported\',action=\'store_true\');g.add_argument(\'--normal-first\',action=\'store_true\');a=p.parse_args();run(a.source,a.dest,a.stems.read_text().split(),a.data,a.candidates,a.supported,a.normal_first)\n')
(ADDON/'runtime'/'boundary_mean1_post.py').write_text('"""Prediction-only boundary1 mean-ratio restore after selective size8 postprocess."""\nfrom __future__ import annotations\n\nimport copy\nimport pickle\nfrom collections import defaultdict\nfrom pathlib import Path\nfrom typing import Any\n\nimport numpy as np\nimport zarr\nfrom scipy.spatial import cKDTree\n\nSCALE = np.asarray([1.625, .40625, .40625])\nMIN_TRACK_LEN = 9\nMIN_TRACK_LEN_BY_DATASET: dict[str, int] = {}\n\n\ndef base_short_track_filter(\n    nodes: dict[int, dict[str, Any]],\n    edges: list[dict[str, Any]],\n    dataset: str,\n    stats: defaultdict[str, int],\n) -> tuple[dict[int, dict[str, Any]], list[dict[str, Any]]]:\n    minimum = MIN_TRACK_LEN_BY_DATASET.get(dataset, MIN_TRACK_LEN)\n    stats["short_track_min_len_effective"] = minimum\n    parent = {node_id: node_id for node_id in nodes}\n\n    def find(node_id: int) -> int:\n        while parent[node_id] != node_id:\n            parent[node_id] = parent[parent[node_id]]\n            node_id = parent[node_id]\n        return node_id\n\n    def union(a: int, b: int) -> None:\n        root_a, root_b = find(a), find(b)\n        if root_a != root_b:\n            parent[root_a] = root_b\n\n    out_count: defaultdict[int, int] = defaultdict(int)\n    for edge in edges:\n        source_id, target_id = int(edge["source_id"]), int(edge["target_id"])\n        union(source_id, target_id)\n        out_count[source_id] += 1\n    components: dict[int, list[int]] = defaultdict(list)\n    for node_id in nodes:\n        components[find(node_id)].append(node_id)\n    keep: set[int] = set()\n    for members in components.values():\n        has_division = any(out_count[node_id] >= 2 for node_id in members)\n        if len(members) >= minimum or has_division:\n            keep.update(members)\n    if not keep:\n        stats["short_track_filter_skipped_all"] += 1\n        return nodes, edges\n    kept_nodes = {node_id: node for node_id, node in nodes.items() if node_id in keep}\n    kept_edges = [\n        edge for edge in edges\n        if int(edge["source_id"]) in kept_nodes and int(edge["target_id"]) in kept_nodes\n    ]\n    stats["short_track_components_removed"] = sum(not (set(members) & keep) for members in components.values())\n    stats["short_track_nodes_removed"] = len(nodes) - len(kept_nodes)\n    stats["short_track_edges_removed"] = len(edges) - len(kept_edges)\n    return kept_nodes, kept_edges\n\n\ndef edge_ids(edges: list[dict]) -> set[tuple[int, int]]:\n    return {(int(edge[\'source_id\']), int(edge[\'target_id\'])) for edge in edges}\n\n\ndef groups_of_extra(extra: set[int], edge_pairs: set[tuple[int, int]]) -> list[list[int]]:\n    adjacency = {node_id: set() for node_id in extra}\n    for source_id, target_id in edge_pairs:\n        if source_id in extra or target_id in extra:\n            assert source_id in extra and target_id in extra, \'extra component attaches to control\'\n            adjacency[source_id].add(target_id)\n            adjacency[target_id].add(source_id)\n    groups = []\n    unseen = set(extra)\n    while unseen:\n        stack = [min(unseen)]\n        group = set()\n        while stack:\n            node_id = stack.pop()\n            if node_id in group:\n                continue\n            group.add(node_id)\n            stack.extend(adjacency[node_id] - group)\n        unseen -= group\n        groups.append(sorted(group))\n    return groups\n\n\ndef apply(raw: dict, raw_edges: list[dict], final: dict, final_edges: list[dict],\n          stem: str, data: Path, candidates: Path, b, stats: dict) -> tuple[dict, list[dict]]:\n    """Return size8 graph plus boundary components satisfying both relative-score gates."""\n    rows = pickle.loads((candidates / f\'{stem}.pkl\').read_bytes())[\'node_rows\']\n    assert all(\n        node_id < len(rows) and int(node[\'t\']) == int(rows[node_id][\'t\'])\n        and all(abs(float(node[axis]) - float(rows[node_id][axis])) < 1e-5 for axis in (\'z\', \'y\', \'x\'))\n        for node_id, node in raw.items()\n    ), stem\n    current_filter, current_min = b.short_track_filter, b.MIN_TRACK_LEN\n    assert current_min == 9 and b.MIN_TRACK_LEN_BY_DATASET == {}, stem\n    try:\n        b.short_track_filter = base_short_track_filter\n        control, control_edges, _ = b.apply_arm(\'gap_short_track_linefit\', raw, raw_edges, stem, data)\n        b.short_track_filter = current_filter\n        b.MIN_TRACK_LEN = 3\n        short, short_edges, _ = b.apply_arm(\'gap_short_track_linefit\', raw, raw_edges, stem, data)\n    finally:\n        b.short_track_filter = current_filter\n        b.MIN_TRACK_LEN = current_min\n    assert set(control) <= set(final) <= set(short), stem\n    control_pairs, final_pairs, short_pairs = map(edge_ids, (control_edges, final_edges, short_edges))\n    assert control_pairs <= final_pairs <= short_pairs, stem\n    extra = set(short) - set(control)\n    groups = groups_of_extra(extra, short_pairs)\n    bytime: dict[int, list[int]] = defaultdict(list)\n    for node_id in control:\n        if node_id in raw:\n            bytime[int(rows[node_id][\'t\'])].append(node_id)\n    trees = {\n        t: cKDTree(np.asarray([[rows[k][axis] for axis in (\'z\', \'y\', \'x\')] for k in ids]) * SCALE)\n        for t, ids in bytime.items()\n    }\n    frames = int(zarr.open_group(str(data / f\'{stem}.zarr\'), mode=\'r\')[\'0\'].shape[0])\n    selected = []\n    for ids in groups:\n        times = [int(short[k][\'t\']) for k in ids]\n        assert 3 <= len(ids) <= 8 and len(times) == len(set(times)), (stem, len(ids))\n        ratios = []\n        missing = 0\n        for node_id in ids:\n            t = int(rows[node_id][\'t\']) if node_id in raw else -1\n            if node_id not in raw or t not in bytime:\n                missing += 1\n                continue\n            pool = bytime[t]\n            loc = np.asarray([rows[node_id][axis] for axis in (\'z\', \'y\', \'x\')]) * SCALE\n            near = trees[t].query_ball_point(loc, 7.)\n            score = (max(rows[pool[j]][\'node_score\'] for j in near) if near\n                     else float(np.median([rows[j][\'node_score\'] for j in pool])))\n            ratios.append(float(rows[node_id][\'node_score\']) / max(float(score), 1e-12))\n        boundary = min(times) == 0 or max(times) == frames - 1\n        if boundary and missing == 0 and sum(q >= 1.0 for q in ratios) > len(ids) / 2 and float(np.mean(ratios)) >= 1.0:\n            selected.append(ids)\n    selected_ids = {k for ids in selected for k in ids}\n    trial_nodes = copy.deepcopy(final)\n    trial_nodes.update({k: copy.deepcopy(short[k]) for k in selected_ids if k not in trial_nodes})\n    pairs = final_pairs | {(u, v) for u, v in short_pairs if u in selected_ids and v in selected_ids}\n    assert max(abs(float(trial_nodes[k][axis]) - float(final[k][axis]))\n               for k in final for axis in (\'z\', \'y\', \'x\')) < 1e-6, stem\n    trial_edges = [dict(source_id=u, target_id=v) for u, v in sorted(pairs)]\n    b.validate_and_clip_graph(trial_nodes, trial_edges, stem, data, defaultdict(int))\n    stats[\'boundary_mean1_components_kept\'] = len(selected)\n    stats[\'boundary_mean1_added_nodes_vs_size8\'] = len(trial_nodes) - len(final)\n    stats[\'boundary_mean1_added_edges_vs_size8\'] = len(pairs) - len(final_pairs)\n    return trial_nodes, trial_edges\n')
(ADDON/'runtime'/'postbest.py').write_text('#!/usr/bin/env python3\n"""Apply fixed LB0.897-style graph repairs to existing Biohub GEFF outputs."""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport json\nimport math\nimport shutil\nimport traceback\nfrom collections import defaultdict\nfrom pathlib import Path\nfrom typing import Any\n\nimport numpy as np\nimport polars as pl\nimport tracksdata as td\nimport zarr\nfrom scipy.optimize import linear_sum_assignment\nfrom scipy.spatial.distance import cdist\n\n\nVOXEL_SCALE_UM = np.asarray((1.625, 0.40625, 0.40625), dtype=np.float64)\n\nMOTION_TIGHT_UM = 6.0\nMOTION_RELAXED_UM = 10.0\nMOTION_VELOCITY_WEIGHT = 0.5\nMOTION_LEARNED_BONUS = 0.0\nMOTION_MAX_FRAME_NODES = 2600\n\nGAP_CLOSE_UM = 6.0\nGAP_REUSE_UM = 3.2\nGAP_MAX_ADDED_FRAC = 0.05\nGAP_MAX_ADDED_ABS = 2000\nGAP_REFINE_WIN_Z = 1\nGAP_REFINE_WIN_YX = 3\nGAP_REFINE_MAX_SHIFT_UM = 3.2\n\nMIN_TRACK_LEN = 7\nMIN_TRACK_LEN_BY_DATASET = {"6bba_05b6850b": 6}\nLINEFIT_WEIGHT = 0.8\nLINEFIT_WINDOW = 2\nLINEFIT_CAP_UM = 2.0\nLINEFIT_HUBER_DELTA_UM = 1.5\nKALMAN_PROCESS_VAR = 0.20\nKALMAN_MEASUREMENT_VAR = 1.0\nGRAPH_ACCEL_LAMBDA = 2.0\nPOSTPROCESS_MAX_NODES = 200_000\nPOSTPROCESS_MAX_EDGES = 200_000\n\nSAFE_DIV_MAX_UM = 4.7\nSAFE_DIV_SISTER_MAX_UM = 7.2\nSAFE_DIV_EXISTING_CHILD_MAX_UM = 7.8\nSAFE_DIV_FRAME_FRAC_CAP = 0.008\nSAFE_DIV_GLOBAL_FRAC_CAP = 0.004\n\nARMS = (\n    "gap_close",\n    "short_track",\n    "linefit",\n    "motion_relink",\n    "safe_division",\n    "full_stack",\n    "short_track_linefit",\n    "gap_short_track",\n    "gap_short_track_linefit",\n    "gap_short_track_linefit_cap20",\n    "gap_short_track_linefit_huber_cap20",\n    "gap_short_track_kalman_rts_cap20",\n    "gap_short_track_graph_accel_cap20",\n)\n\n\ndef read_graph(path: Path) -> tuple[dict[int, dict[str, Any]], list[dict[str, Any]]]:\n    loaded = td.graph.IndexedRXGraph.from_geff(path)\n    graph = loaded[0] if isinstance(loaded, tuple) else loaded\n    nodes = {\n        int(row["node_id"]): {\n            "node_id": int(row["node_id"]),\n            "t": int(row["t"]),\n            "z": float(row["z"]),\n            "y": float(row["y"]),\n            "x": float(row["x"]),\n        }\n        for row in graph.node_attrs().iter_rows(named=True)\n    }\n    edges: list[dict[str, Any]] = []\n    for row in graph.edge_attrs().iter_rows(named=True):\n        source_id = int(row["source_id"])\n        target_id = int(row["target_id"])\n        prob = row.get("edge_prob")\n        edges.append(\n            {\n                "source_id": source_id,\n                "target_id": target_id,\n                "edge_prob": None if prob is None else float(prob),\n                "distance_um": edge_distance_um(nodes[source_id], nodes[target_id]),\n            }\n        )\n    return nodes, edges\n\n\ndef write_graph(\n    path: Path,\n    nodes: dict[int, dict[str, Any]],\n    edges: list[dict[str, Any]],\n) -> None:\n    graph = td.graph.IndexedRXGraph()\n    for axis in ("z", "y", "x"):\n        graph.add_node_attr_key(axis, dtype=pl.Float64)\n    ordered_ids = sorted(nodes)\n    graph.bulk_add_nodes(\n        [\n            {\n                "t": int(nodes[node_id]["t"]),\n                "z": float(nodes[node_id]["z"]),\n                "y": float(nodes[node_id]["y"]),\n                "x": float(nodes[node_id]["x"]),\n            }\n            for node_id in ordered_ids\n        ],\n        indices=ordered_ids,\n    )\n    if edges:\n        graph.bulk_add_edges(\n            [\n                {\n                    "source_id": int(edge["source_id"]),\n                    "target_id": int(edge["target_id"]),\n                }\n                for edge in edges\n            ]\n        )\n    path.parent.mkdir(parents=True, exist_ok=True)\n    graph.to_geff(path, overwrite=True)\n\n\ndef edge_distance_um(source: dict[str, Any], target: dict[str, Any]) -> float:\n    a = np.asarray((source["z"], source["y"], source["x"]), dtype=np.float64)\n    b = np.asarray((target["z"], target["y"], target["x"]), dtype=np.float64)\n    return float(np.linalg.norm((a - b) * VOXEL_SCALE_UM))\n\n\ndef point_distance_um(a: tuple[float, float, float], b: tuple[float, float, float]) -> float:\n    return float(np.linalg.norm((np.asarray(a) - np.asarray(b)) * VOXEL_SCALE_UM))\n\n\ndef node_point(node: dict[str, Any]) -> tuple[float, float, float]:\n    return float(node["z"]), float(node["y"]), float(node["x"])\n\n\ndef position_um(node: dict[str, Any]) -> np.ndarray:\n    return np.asarray(node_point(node), dtype=np.float64) * VOXEL_SCALE_UM\n\n\ndef motion_relink(\n    nodes: dict[int, dict[str, Any]],\n    stats: defaultdict[str, int],\n    learned_edge_probs: dict[tuple[int, int], float] | None = None,\n) -> list[dict[str, Any]]:\n    learned_edge_probs = learned_edge_probs or {}\n\n    def learned_prob(source_id: int, target_id: int) -> float:\n        value = learned_edge_probs.get((source_id, target_id), 0.0)\n        try:\n            value = float(value)\n        except (TypeError, ValueError):\n            return 0.0\n        if not np.isfinite(value):\n            return 0.0\n        if value < 0.0 or value > 1.0:\n            value = 1.0 / (1.0 + math.exp(-max(-20.0, min(20.0, value))))\n        return float(np.clip(value, 0.0, 1.0))\n\n    ids_by_t: dict[int, list[int]] = defaultdict(list)\n    for node_id, node in nodes.items():\n        ids_by_t[int(node["t"])].append(node_id)\n    for ids in ids_by_t.values():\n        ids.sort()\n    if ids_by_t and max(map(len, ids_by_t.values())) > MOTION_MAX_FRAME_NODES:\n        stats["motion_relink_skipped_large_frame"] = 1\n        return []\n\n    pos = {node_id: position_um(node) for node_id, node in nodes.items()}\n    predecessor_pos: dict[int, np.ndarray] = {}\n    selected: list[dict[str, Any]] = []\n\n    def assign(source_ids: list[int], target_ids: list[int], gate: float):\n        if not source_ids or not target_ids:\n            return []\n        big = gate * 1000.0 + 1.0\n        source_pos = np.stack([pos[node_id] for node_id in source_ids])\n        target_pos = np.stack([pos[node_id] for node_id in target_ids])\n        predicted_pos = np.stack(\n            [\n                current\n                if (previous := predecessor_pos.get(node_id)) is None\n                else current + MOTION_VELOCITY_WEIGHT * (current - previous)\n                for node_id, current in zip(source_ids, source_pos)\n            ]\n        )\n        raw_distance = cdist(source_pos, target_pos)\n        motion_distance = cdist(predicted_pos, target_pos)\n        probability = np.asarray(\n            [\n                [learned_prob(source_id, target_id) for target_id in target_ids]\n                for source_id in source_ids\n            ],\n            dtype=np.float64,\n        )\n        cost = np.where(\n            raw_distance <= gate,\n            motion_distance + 0.05 * raw_distance - MOTION_LEARNED_BONUS * probability,\n            big,\n        )\n        rows, cols = linear_sum_assignment(cost)\n        return [\n            (\n                source_ids[int(r)],\n                target_ids[int(c)],\n                float(raw_distance[r, c]),\n                float(motion_distance[r, c]),\n                float(probability[r, c]),\n            )\n            for r, c in zip(rows, cols)\n            if cost[r, c] < big\n        ]\n\n    for t in sorted(ids_by_t):\n        source_ids = ids_by_t[t]\n        target_ids = ids_by_t.get(t + 1, [])\n        unmatched_sources = set(source_ids)\n        unmatched_targets = set(target_ids)\n        for pass_name, gate in (("tight", MOTION_TIGHT_UM), ("relaxed", MOTION_RELAXED_UM)):\n            matches = assign(\n                [x for x in source_ids if x in unmatched_sources],\n                [x for x in target_ids if x in unmatched_targets],\n                gate,\n            )\n            for source_id, target_id, raw, motion, probability in matches:\n                if source_id not in unmatched_sources or target_id not in unmatched_targets:\n                    continue\n                unmatched_sources.remove(source_id)\n                unmatched_targets.remove(target_id)\n                selected.append(\n                    {\n                        "source_id": source_id,\n                        "target_id": target_id,\n                        "edge_prob": probability,\n                        "distance_um": raw,\n                        "motion_distance_um": motion,\n                        "motion_pass": pass_name,\n                    }\n                )\n                predecessor_pos[target_id] = pos[source_id]\n                stats[f"motion_relink_{pass_name}_edges"] += 1\n        stats["motion_relink_frames"] += 1\n    stats["motion_relink_edges"] = len(selected)\n    stats["motion_relink_learned_bonus_milli"] = int(round(MOTION_LEARNED_BONUS * 1000))\n    return selected\n\n\ndef refine_midpoint(\n    data_dir: Path,\n    dataset: str,\n    t: int,\n    midpoint: tuple[float, float, float],\n    frame_cache: dict[int, np.ndarray],\n    stats: defaultdict[str, int],\n) -> tuple[float, float, float]:\n    try:\n        if t not in frame_cache:\n            frame_cache[t] = np.asarray(\n                zarr.open_group(str(data_dir / f"{dataset}.zarr"), mode="r")["0"][t]\n            )\n        frame = frame_cache[t]\n        z, y, x = (int(round(value)) for value in midpoint)\n        z0, z1 = max(0, z - GAP_REFINE_WIN_Z), min(frame.shape[0], z + GAP_REFINE_WIN_Z + 1)\n        y0, y1 = max(0, y - GAP_REFINE_WIN_YX), min(frame.shape[1], y + GAP_REFINE_WIN_YX + 1)\n        x0, x1 = max(0, x - GAP_REFINE_WIN_YX), min(frame.shape[2], x + GAP_REFINE_WIN_YX + 1)\n        patch = frame[z0:z1, y0:y1, x0:x1].astype(np.float64)\n        baseline = float(np.percentile(patch, 20.0))\n        weights = np.maximum(patch - baseline, 0.0)\n        total = float(weights.sum())\n        if patch.size == 0 or total <= 0:\n            raise ValueError("empty refinement weights")\n        zz = np.arange(z0, z1, dtype=np.float64)[:, None, None]\n        yy = np.arange(y0, y1, dtype=np.float64)[None, :, None]\n        xx = np.arange(x0, x1, dtype=np.float64)[None, None, :]\n        refined = (\n            float((weights * zz).sum() / total),\n            float((weights * yy).sum() / total),\n            float((weights * xx).sum() / total),\n        )\n        if point_distance_um(refined, midpoint) > GAP_REFINE_MAX_SHIFT_UM:\n            stats["gap_refine_rejected_shift"] += 1\n            return midpoint\n        stats["gap_refined_synthetic"] += 1\n        return refined\n    except Exception:\n        stats["gap_refine_failed"] += 1\n        return midpoint\n\n\ndef gap_close(\n    nodes: dict[int, dict[str, Any]],\n    edges: list[dict[str, Any]],\n    dataset: str,\n    data_dir: Path,\n    stats: defaultdict[str, int],\n) -> tuple[dict[int, dict[str, Any]], list[dict[str, Any]]]:\n    if not edges:\n        return nodes, edges\n    outgoing = {int(edge["source_id"]) for edge in edges}\n    incoming = {int(edge["target_id"]) for edge in edges}\n    incident = outgoing | incoming\n    ends_by_t: dict[int, list[int]] = defaultdict(list)\n    starts_by_t: dict[int, list[int]] = defaultdict(list)\n    isolated_by_t: dict[int, list[int]] = defaultdict(list)\n    for node_id, node in nodes.items():\n        t = int(node["t"])\n        if node_id not in outgoing:\n            ends_by_t[t].append(node_id)\n        if node_id not in incoming:\n            starts_by_t[t].append(node_id)\n        if node_id not in incident:\n            isolated_by_t[t].append(node_id)\n    max_synthetic = min(GAP_MAX_ADDED_ABS, max(1, round(len(nodes) * GAP_MAX_ADDED_FRAC)))\n    next_id = max(nodes, default=0) + 1\n    used_starts: set[int] = set()\n    used_isolated: set[int] = set()\n    frame_cache: dict[int, np.ndarray] = {}\n    new_edges: list[dict[str, Any]] = []\n    synthetic_added = 0\n    for t, end_ids in sorted(ends_by_t.items()):\n        start_ids = [node_id for node_id in starts_by_t.get(t + 2, []) if node_id not in used_starts]\n        if not end_ids or not start_ids:\n            continue\n        distances = np.asarray(\n            [[point_distance_um(node_point(nodes[a]), node_point(nodes[b])) for b in start_ids] for a in end_ids]\n        )\n        threshold = GAP_CLOSE_UM * 2.0\n        stats["gap_candidates"] += int((distances <= threshold).sum())\n        big = threshold * 1000.0 + 1.0\n        rows, cols = linear_sum_assignment(np.where(distances <= threshold, distances, big))\n        for r, c in zip(rows, cols):\n            if distances[r, c] > threshold:\n                continue\n            source_id, target_id = end_ids[int(r)], start_ids[int(c)]\n            if source_id in outgoing or target_id in used_starts:\n                continue\n            source, target = nodes[source_id], nodes[target_id]\n            mid_t = int(source["t"]) + 1\n            midpoint = tuple((a + b) / 2.0 for a, b in zip(node_point(source), node_point(target)))\n            middle_id: int | None = None\n            candidates = [x for x in isolated_by_t.get(mid_t, []) if x not in used_isolated]\n            if candidates:\n                candidate_distances = [point_distance_um(node_point(nodes[x]), midpoint) for x in candidates]\n                best = int(np.argmin(candidate_distances))\n                if candidate_distances[best] <= GAP_REUSE_UM:\n                    middle_id = candidates[best]\n                    used_isolated.add(middle_id)\n                    stats["gap_reused_existing"] += 1\n            if middle_id is None:\n                if synthetic_added >= max_synthetic:\n                    stats["gap_skipped_node_cap"] += 1\n                    continue\n                middle_id = next_id\n                next_id += 1\n                refined = refine_midpoint(data_dir, dataset, mid_t, midpoint, frame_cache, stats)\n                nodes[middle_id] = {\n                    "node_id": middle_id,\n                    "t": mid_t,\n                    "z": refined[0],\n                    "y": refined[1],\n                    "x": refined[2],\n                }\n                synthetic_added += 1\n                stats["gap_inserted_synthetic"] += 1\n            middle = nodes[middle_id]\n            new_edges.extend(\n                [\n                    {"source_id": source_id, "target_id": middle_id, "edge_prob": None, "distance_um": edge_distance_um(source, middle)},\n                    {"source_id": middle_id, "target_id": target_id, "edge_prob": None, "distance_um": edge_distance_um(middle, target)},\n                ]\n            )\n            outgoing.update((source_id, middle_id))\n            incoming.update((middle_id, target_id))\n            used_starts.add(target_id)\n            stats["gap_pairs_selected"] += 1\n            stats["gap_added_edges"] += 2\n    stats["gap_added_nodes"] = synthetic_added\n    return nodes, [*edges, *new_edges]\n\n\ndef safe_division(\n    nodes: dict[int, dict[str, Any]],\n    edges: list[dict[str, Any]],\n    stats: defaultdict[str, int],\n) -> list[dict[str, Any]]:\n    out_by_source: dict[int, list[dict[str, Any]]] = defaultdict(list)\n    incoming: set[int] = set()\n    for edge in edges:\n        out_by_source[int(edge["source_id"])].append(edge)\n        incoming.add(int(edge["target_id"]))\n    ids_by_t: dict[int, list[int]] = defaultdict(list)\n    for node_id, node in nodes.items():\n        ids_by_t[int(node["t"])].append(node_id)\n    existing = {(int(edge["source_id"]), int(edge["target_id"])) for edge in edges}\n    global_cap = max(1, round(max(1, len(edges)) * SAFE_DIV_GLOBAL_FRAC_CAP))\n    added: list[dict[str, Any]] = []\n    used_targets: set[int] = set()\n    for t in sorted(ids_by_t):\n        sources = [x for x in ids_by_t[t] if len(out_by_source.get(x, [])) == 1]\n        candidates = [x for x in ids_by_t.get(t + 1, []) if x not in incoming and x not in used_targets]\n        frame_cap = max(1, round(len(sources) * SAFE_DIV_FRAME_FRAC_CAP))\n        proposals: list[tuple[float, int, int, float]] = []\n        for source_id in sources:\n            child_id = int(out_by_source[source_id][0]["target_id"])\n            child = nodes[child_id]\n            if edge_distance_um(nodes[source_id], child) > SAFE_DIV_EXISTING_CHILD_MAX_UM:\n                continue\n            for candidate_id in candidates:\n                if (source_id, candidate_id) in existing:\n                    continue\n                parent_distance = edge_distance_um(nodes[source_id], nodes[candidate_id])\n                sister_distance = edge_distance_um(child, nodes[candidate_id])\n                if parent_distance <= SAFE_DIV_MAX_UM and sister_distance <= SAFE_DIV_SISTER_MAX_UM:\n                    proposals.append((parent_distance + 0.15 * sister_distance, source_id, candidate_id, parent_distance))\n        stats["safe_division_candidates"] += len(proposals)\n        added_this_frame = 0\n        for _, source_id, candidate_id, parent_distance in sorted(proposals):\n            if len(added) >= global_cap or added_this_frame >= frame_cap:\n                break\n            if candidate_id in incoming or candidate_id in used_targets:\n                continue\n            added.append(\n                {"source_id": source_id, "target_id": candidate_id, "edge_prob": None, "distance_um": parent_distance}\n            )\n            used_targets.add(candidate_id)\n            added_this_frame += 1\n    stats["safe_divisions_added"] = len(added)\n    return [*edges, *added]\n\n\ndef short_track_filter(\n    nodes: dict[int, dict[str, Any]],\n    edges: list[dict[str, Any]],\n    dataset: str,\n    stats: defaultdict[str, int],\n) -> tuple[dict[int, dict[str, Any]], list[dict[str, Any]]]:\n    minimum = MIN_TRACK_LEN_BY_DATASET.get(dataset, MIN_TRACK_LEN)\n    stats["short_track_min_len_effective"] = minimum\n    parent = {node_id: node_id for node_id in nodes}\n\n    def find(node_id: int) -> int:\n        while parent[node_id] != node_id:\n            parent[node_id] = parent[parent[node_id]]\n            node_id = parent[node_id]\n        return node_id\n\n    def union(a: int, b: int) -> None:\n        root_a, root_b = find(a), find(b)\n        if root_a != root_b:\n            parent[root_a] = root_b\n\n    out_count: defaultdict[int, int] = defaultdict(int)\n    for edge in edges:\n        source_id, target_id = int(edge["source_id"]), int(edge["target_id"])\n        union(source_id, target_id)\n        out_count[source_id] += 1\n    components: dict[int, list[int]] = defaultdict(list)\n    for node_id in nodes:\n        components[find(node_id)].append(node_id)\n    component_edges = defaultdict(list)\n    for edge in edges:\n        component_edges[find(int(edge[\'source_id\']))].append(edge)\n    keep: set[int] = set()\n    for members in components.values():\n        has_division = any(out_count[node_id] >= 2 for node_id in members)\n        selective_keep = False\n        if len(members) == 8 and not has_division:\n            native_edges = component_edges[find(members[0])]\n            probabilities = [edge.get(\'edge_prob\') for edge in native_edges]\n            if probabilities and all(p is not None and math.isfinite(float(p)) for p in probabilities):\n                probs = [float(p) for p in probabilities]\n                selective_keep = sum(probs) / len(probs) >= 0.5\n            if selective_keep:\n                stats[\'selective_size8_components_kept\'] += 1\n                stats[\'selective_size8_nodes_kept\'] += len(members)\n        if len(members) >= minimum or has_division or selective_keep:\n            keep.update(members)\n    if not keep:\n        stats["short_track_filter_skipped_all"] += 1\n        return nodes, edges\n    kept_nodes = {node_id: node for node_id, node in nodes.items() if node_id in keep}\n    kept_edges = [\n        edge for edge in edges\n        if int(edge["source_id"]) in kept_nodes and int(edge["target_id"]) in kept_nodes\n    ]\n    stats["short_track_components_removed"] = sum(not (set(members) & keep) for members in components.values())\n    stats["short_track_nodes_removed"] = len(nodes) - len(kept_nodes)\n    stats["short_track_edges_removed"] = len(edges) - len(kept_edges)\n    return kept_nodes, kept_edges\n\n\ndef linefit(\n    nodes: dict[int, dict[str, Any]],\n    edges: list[dict[str, Any]],\n    stats: defaultdict[str, int],\n) -> dict[int, dict[str, Any]]:\n    predecessor: dict[int, list[int]] = defaultdict(list)\n    successor: dict[int, list[int]] = defaultdict(list)\n    for edge in edges:\n        source_id, target_id = int(edge["source_id"]), int(edge["target_id"])\n        if int(nodes[target_id]["t"]) == int(nodes[source_id]["t"]) + 1:\n            successor[source_id].append(target_id)\n            predecessor[target_id].append(source_id)\n    original = {node_id: np.asarray(node_point(node), dtype=np.float64) for node_id, node in nodes.items()}\n    updated: dict[int, np.ndarray] = {}\n    for node_id in sorted(nodes):\n        neighbourhood = [(0, node_id)]\n        current = node_id\n        for step in range(1, LINEFIT_WINDOW + 1):\n            previous = predecessor.get(current, [])\n            if len(previous) != 1:\n                break\n            current = previous[0]\n            neighbourhood.append((-step, current))\n        current = node_id\n        for step in range(1, LINEFIT_WINDOW + 1):\n            following = successor.get(current, [])\n            if len(following) != 1:\n                break\n            current = following[0]\n            neighbourhood.append((step, current))\n        if len(neighbourhood) < 3:\n            stats["linefit_skipped_nodes"] += 1\n            continue\n        dts = np.asarray([delta for delta, _ in neighbourhood], dtype=np.float64)\n        coords = np.stack([original[x] for _, x in neighbourhood])\n        fitted = np.asarray([np.polyval(np.polyfit(dts, coords[:, axis], 1), 0.0) for axis in range(3)])\n        if np.isfinite(fitted).all():\n            updated[node_id] = (1.0 - LINEFIT_WEIGHT) * original[node_id] + LINEFIT_WEIGHT * fitted\n    for node_id, point in updated.items():\n        nodes[node_id].update(z=float(point[0]), y=float(point[1]), x=float(point[2]))\n    stats["linefit_smoothed_nodes"] = len(updated)\n    return nodes\n\n\ndef clip_physical_displacement(\n    original: np.ndarray, proposed: np.ndarray, cap_um: float\n) -> tuple[np.ndarray, float, bool]:\n    """Clip a ZYX displacement by its physical-space Euclidean norm."""\n    delta = proposed - original\n    norm_um = float(np.linalg.norm(delta * VOXEL_SCALE_UM))\n    if not math.isfinite(norm_um) or norm_um <= cap_um:\n        return proposed, norm_um, False\n    return original + delta * (cap_um / norm_um), norm_um, True\n\n\ndef trajectory_neighbourhoods(\n    nodes: dict[int, dict[str, Any]], edges: list[dict[str, Any]]\n) -> dict[int, list[tuple[int, int]]]:\n    predecessor: dict[int, list[int]] = defaultdict(list)\n    successor: dict[int, list[int]] = defaultdict(list)\n    for edge in edges:\n        source_id, target_id = int(edge["source_id"]), int(edge["target_id"])\n        if int(nodes[target_id]["t"]) == int(nodes[source_id]["t"]) + 1:\n            successor[source_id].append(target_id)\n            predecessor[target_id].append(source_id)\n    result: dict[int, list[tuple[int, int]]] = {}\n    for node_id in sorted(nodes):\n        neighbourhood = [(0, node_id)]\n        current = node_id\n        for step in range(1, LINEFIT_WINDOW + 1):\n            previous = predecessor.get(current, [])\n            if len(previous) != 1:\n                break\n            current = previous[0]\n            neighbourhood.append((-step, current))\n        current = node_id\n        for step in range(1, LINEFIT_WINDOW + 1):\n            following = successor.get(current, [])\n            if len(following) != 1:\n                break\n            current = following[0]\n            neighbourhood.append((step, current))\n        result[node_id] = sorted(neighbourhood)\n    return result\n\n\ndef weighted_linear_prediction_at_zero(\n    dts: np.ndarray, coords: np.ndarray, weights: np.ndarray\n) -> np.ndarray:\n    design = np.column_stack((dts, np.ones_like(dts)))\n    sqrt_weights = np.sqrt(np.maximum(weights, 1e-8))[:, None]\n    coefficients, *_ = np.linalg.lstsq(\n        design * sqrt_weights, coords * sqrt_weights, rcond=None\n    )\n    return coefficients[1]\n\n\ndef safer_local_linefit(\n    nodes: dict[int, dict[str, Any]],\n    edges: list[dict[str, Any]],\n    stats: defaultdict[str, int],\n    robust: bool,\n    cap_um: float,\n) -> dict[int, dict[str, Any]]:\n    original = {\n        node_id: np.asarray(node_point(node), dtype=np.float64)\n        for node_id, node in nodes.items()\n    }\n    updated: dict[int, np.ndarray] = {}\n    raw_shifts: list[float] = []\n    final_shifts: list[float] = []\n    for node_id, neighbourhood in trajectory_neighbourhoods(nodes, edges).items():\n        if len(neighbourhood) < 3:\n            stats["linefit_skipped_nodes"] += 1\n            continue\n        dts = np.asarray([delta for delta, _ in neighbourhood], dtype=np.float64)\n        coords = np.stack([original[x] for _, x in neighbourhood])\n        weights = np.ones(len(neighbourhood), dtype=np.float64)\n        fitted = weighted_linear_prediction_at_zero(dts, coords, weights)\n        if robust:\n            for _ in range(4):\n                design = np.column_stack((dts, np.ones_like(dts)))\n                sqrt_weights = np.sqrt(np.maximum(weights, 1e-8))[:, None]\n                coefficients, *_ = np.linalg.lstsq(\n                    design * sqrt_weights, coords * sqrt_weights, rcond=None\n                )\n                residual_um = np.linalg.norm(\n                    (coords - design @ coefficients) * VOXEL_SCALE_UM[None, :], axis=1\n                )\n                weights = np.minimum(\n                    1.0, LINEFIT_HUBER_DELTA_UM / np.maximum(residual_um, 1e-8)\n                )\n            fitted = coefficients[1]\n        proposed = (1.0 - LINEFIT_WEIGHT) * original[node_id] + LINEFIT_WEIGHT * fitted\n        if not np.isfinite(proposed).all():\n            stats["linefit_nonfinite_nodes"] += 1\n            continue\n        clipped, raw_shift, was_clipped = clip_physical_displacement(\n            original[node_id], proposed, cap_um\n        )\n        raw_shifts.append(raw_shift)\n        final_shifts.append(float(np.linalg.norm((clipped - original[node_id]) * VOXEL_SCALE_UM)))\n        stats["linefit_clipped_nodes"] += int(was_clipped)\n        updated[node_id] = clipped\n    for node_id, point in updated.items():\n        nodes[node_id].update(z=float(point[0]), y=float(point[1]), x=float(point[2]))\n    stats["linefit_smoothed_nodes"] = len(updated)\n    stats["linefit_robust"] = int(robust)\n    if raw_shifts:\n        stats["linefit_raw_shift_mean_milli_um"] = round(float(np.mean(raw_shifts)) * 1000)\n        stats["linefit_final_shift_mean_milli_um"] = round(float(np.mean(final_shifts)) * 1000)\n    return nodes\n\n\ndef nonbranching_chains(\n    nodes: dict[int, dict[str, Any]], edges: list[dict[str, Any]]\n) -> list[list[int]]:\n    predecessor: dict[int, list[int]] = defaultdict(list)\n    successor: dict[int, list[int]] = defaultdict(list)\n    for edge in edges:\n        source_id, target_id = int(edge["source_id"]), int(edge["target_id"])\n        if int(nodes[target_id]["t"]) == int(nodes[source_id]["t"]) + 1:\n            successor[source_id].append(target_id)\n            predecessor[target_id].append(source_id)\n    starts = [\n        node_id for node_id in nodes\n        if len(predecessor.get(node_id, [])) != 1\n        or len(successor.get(predecessor[node_id][0], [])) != 1\n    ]\n    visited: set[int] = set()\n    chains: list[list[int]] = []\n    for start in sorted(starts, key=lambda x: (int(nodes[x]["t"]), x)):\n        if start in visited:\n            continue\n        chain = [start]\n        visited.add(start)\n        current = start\n        while len(successor.get(current, [])) == 1:\n            target = successor[current][0]\n            if len(predecessor.get(target, [])) != 1 or target in visited:\n                break\n            chain.append(target)\n            visited.add(target)\n            current = target\n        chains.append(chain)\n    for node_id in sorted(nodes):\n        if node_id not in visited:\n            chains.append([node_id])\n    return chains\n\n\ndef kalman_rts_positions(observations: np.ndarray) -> np.ndarray:\n    """Constant-velocity Kalman filter and Rauch--Tung--Striebel smoother."""\n    count = len(observations)\n    transition = np.asarray([[1.0, 1.0], [0.0, 1.0]])\n    observe = np.asarray([[1.0, 0.0]])\n    process = KALMAN_PROCESS_VAR * np.asarray([[0.25, 0.5], [0.5, 1.0]])\n    measurement = np.asarray([[KALMAN_MEASUREMENT_VAR]])\n    result = np.empty_like(observations)\n    for axis in range(3):\n        filtered_state: list[np.ndarray] = []\n        filtered_cov: list[np.ndarray] = []\n        predicted_state: list[np.ndarray] = []\n        predicted_cov: list[np.ndarray] = []\n        initial_velocity = observations[1, axis] - observations[0, axis] if count > 1 else 0.0\n        state = np.asarray([observations[0, axis], initial_velocity])\n        covariance = np.eye(2) * 2.0\n        for index in range(count):\n            if index:\n                state = transition @ state\n                covariance = transition @ covariance @ transition.T + process\n            predicted_state.append(state.copy())\n            predicted_cov.append(covariance.copy())\n            innovation = observations[index, axis] - (observe @ state).item()\n            innovation_cov = (observe @ covariance @ observe.T + measurement).item()\n            gain = covariance @ observe.T / innovation_cov\n            state = state + gain[:, 0] * innovation\n            covariance = (np.eye(2) - gain @ observe) @ covariance\n            filtered_state.append(state.copy())\n            filtered_cov.append(covariance.copy())\n        smooth_state = filtered_state[-1].copy()\n        result[-1, axis] = smooth_state[0]\n        for index in range(count - 2, -1, -1):\n            gain = filtered_cov[index] @ transition.T @ np.linalg.pinv(predicted_cov[index + 1])\n            smooth_state = filtered_state[index] + gain @ (\n                smooth_state - predicted_state[index + 1]\n            )\n            result[index, axis] = smooth_state[0]\n    return result\n\n\ndef chain_smooth(\n    nodes: dict[int, dict[str, Any]],\n    edges: list[dict[str, Any]],\n    stats: defaultdict[str, int],\n    mode: str,\n    cap_um: float,\n) -> dict[int, dict[str, Any]]:\n    original_voxel = {\n        node_id: np.asarray(node_point(node), dtype=np.float64)\n        for node_id, node in nodes.items()\n    }\n    updated: dict[int, np.ndarray] = {}\n    for chain in nonbranching_chains(nodes, edges):\n        if len(chain) < 3:\n            stats[f"{mode}_skipped_short_chains"] += 1\n            continue\n        observations_um = np.stack([original_voxel[node_id] * VOXEL_SCALE_UM for node_id in chain])\n        if mode == "kalman_rts":\n            proposed_um = kalman_rts_positions(observations_um)\n        elif mode == "graph_accel":\n            second = np.zeros((len(chain) - 2, len(chain)), dtype=np.float64)\n            for index in range(len(chain) - 2):\n                second[index, index:index + 3] = (1.0, -2.0, 1.0)\n            system = np.eye(len(chain)) + GRAPH_ACCEL_LAMBDA * second.T @ second\n            proposed_um = np.linalg.solve(system, observations_um)\n        else:\n            raise ValueError(f"unknown chain smoothing mode: {mode}")\n        for index, node_id in enumerate(chain):\n            proposed_voxel = proposed_um[index] / VOXEL_SCALE_UM\n            clipped, _, was_clipped = clip_physical_displacement(\n                original_voxel[node_id], proposed_voxel, cap_um\n            )\n            stats[f"{mode}_clipped_nodes"] += int(was_clipped)\n            updated[node_id] = clipped\n    for node_id, point in updated.items():\n        nodes[node_id].update(z=float(point[0]), y=float(point[1]), x=float(point[2]))\n    stats[f"{mode}_smoothed_nodes"] = len(updated)\n    return nodes\n\n\ndef validate_and_clip_graph(\n    nodes: dict[int, dict[str, Any]],\n    edges: list[dict[str, Any]],\n    dataset: str,\n    data_dir: Path,\n    stats: defaultdict[str, int],\n) -> None:\n    """Enforce submission-safe time/coordinate/edge invariants per video."""\n    array = zarr.open_group(str(data_dir / f"{dataset}.zarr"), mode="r")["0"]\n    shape = tuple(int(value) for value in array.shape)\n    if len(shape) != 4 or any(value <= 0 for value in shape):\n        raise ValueError(f"{dataset}: unexpected image shape {shape}")\n    if not nodes:\n        raise ValueError(f"{dataset}: postprocess removed every node")\n\n    clipped_nodes = 0\n    clipped_coordinates = 0\n    upper = np.asarray(shape[1:], dtype=np.float64) - 1.0\n    for node_id, node in nodes.items():\n        t = int(node["t"])\n        if not 0 <= t < shape[0]:\n            raise ValueError(f"{dataset}: node {node_id} has out-of-range t={t}, T={shape[0]}")\n        point = np.asarray(node_point(node), dtype=np.float64)\n        if not np.isfinite(point).all():\n            raise ValueError(f"{dataset}: node {node_id} has non-finite coordinate {point.tolist()}")\n        clipped = np.clip(point, 0.0, upper)\n        changed = ~np.isclose(point, clipped, rtol=0.0, atol=1e-9)\n        if changed.any():\n            clipped_nodes += 1\n            clipped_coordinates += int(changed.sum())\n            node.update(z=float(clipped[0]), y=float(clipped[1]), x=float(clipped[2]))\n\n    seen_edges: set[tuple[int, int]] = set()\n    for edge in edges:\n        source_id = int(edge["source_id"])\n        target_id = int(edge["target_id"])\n        if source_id not in nodes or target_id not in nodes:\n            raise ValueError(f"{dataset}: dangling edge {source_id}->{target_id}")\n        pair = (source_id, target_id)\n        if pair in seen_edges:\n            raise ValueError(f"{dataset}: duplicate edge {source_id}->{target_id}")\n        seen_edges.add(pair)\n        source_t = int(nodes[source_id]["t"])\n        target_t = int(nodes[target_id]["t"])\n        if target_t != source_t + 1:\n            raise ValueError(\n                f"{dataset}: non-consecutive edge {source_id}->{target_id}, "\n                f"times {source_t}->{target_t}"\n            )\n    stats["bounds_clipped_nodes"] += clipped_nodes\n    stats["bounds_clipped_coordinates"] += clipped_coordinates\n    stats["validated_nodes"] = len(nodes)\n    stats["validated_edges"] = len(edges)\n\n\ndef copy_graph_fallback(source: Path, destination: Path) -> None:\n    """Replace a partial postprocess graph with the original valid GEFF."""\n    if destination.exists():\n        if destination.is_dir():\n            shutil.rmtree(destination)\n        else:\n            destination.unlink()\n    destination.parent.mkdir(parents=True, exist_ok=True)\n    if source.is_dir():\n        shutil.copytree(source, destination)\n    else:\n        shutil.copy2(source, destination)\n\n\ndef prune_isolated(\n    nodes: dict[int, dict[str, Any]], edges: list[dict[str, Any]], stats: defaultdict[str, int]\n) -> tuple[dict[int, dict[str, Any]], list[dict[str, Any]]]:\n    incident = {int(edge["source_id"]) for edge in edges} | {int(edge["target_id"]) for edge in edges}\n    if not incident:\n        return nodes, edges\n    kept = {node_id: node for node_id, node in nodes.items() if node_id in incident}\n    stats["pruned_isolated_nodes"] += len(nodes) - len(kept)\n    return kept, edges\n\n\ndef apply_arm(\n    arm: str,\n    source_nodes: dict[int, dict[str, Any]],\n    source_edges: list[dict[str, Any]],\n    dataset: str,\n    data_dir: Path,\n) -> tuple[dict[int, dict[str, Any]], list[dict[str, Any]], dict[str, Any]]:\n    nodes = {node_id: dict(node) for node_id, node in source_nodes.items()}\n    edges = [dict(edge) for edge in source_edges]\n    stats: defaultdict[str, int] = defaultdict(int)\n    if arm in {"motion_relink", "full_stack"}:\n        learned_edge_probs = {\n            (int(edge["source_id"]), int(edge["target_id"])): float(edge["edge_prob"])\n            for edge in source_edges\n            if edge.get("edge_prob") is not None and np.isfinite(float(edge["edge_prob"]))\n        }\n        replacement = motion_relink(nodes, stats, learned_edge_probs)\n        if replacement:\n            edges = replacement\n    if arm in {\n        "gap_close", "full_stack", "gap_short_track", "gap_short_track_linefit",\n        "gap_short_track_linefit_cap20", "gap_short_track_linefit_huber_cap20",\n        "gap_short_track_kalman_rts_cap20", "gap_short_track_graph_accel_cap20",\n    }:\n        nodes, edges = gap_close(nodes, edges, dataset, data_dir, stats)\n    if arm in {"safe_division", "full_stack"}:\n        edges = safe_division(nodes, edges, stats)\n    if arm == "full_stack":\n        nodes, edges = prune_isolated(nodes, edges, stats)\n    if arm in {\n        "short_track", "full_stack", "short_track_linefit",\n        "gap_short_track", "gap_short_track_linefit",\n        "gap_short_track_linefit_cap20", "gap_short_track_linefit_huber_cap20",\n        "gap_short_track_kalman_rts_cap20", "gap_short_track_graph_accel_cap20",\n    }:\n        nodes, edges = short_track_filter(nodes, edges, dataset, stats)\n    if arm in {"linefit", "full_stack", "short_track_linefit", "gap_short_track_linefit"}:\n        nodes = linefit(nodes, edges, stats)\n    if arm == "gap_short_track_linefit_cap20":\n        nodes = safer_local_linefit(nodes, edges, stats, robust=False, cap_um=LINEFIT_CAP_UM)\n    if arm == "gap_short_track_linefit_huber_cap20":\n        nodes = safer_local_linefit(nodes, edges, stats, robust=True, cap_um=LINEFIT_CAP_UM)\n    if arm == "gap_short_track_kalman_rts_cap20":\n        nodes = chain_smooth(nodes, edges, stats, mode="kalman_rts", cap_um=LINEFIT_CAP_UM)\n    if arm == "gap_short_track_graph_accel_cap20":\n        nodes = chain_smooth(nodes, edges, stats, mode="graph_accel", cap_um=LINEFIT_CAP_UM)\n    validate_and_clip_graph(nodes, edges, dataset, data_dir, stats)\n    return nodes, edges, dict(stats)\n\n\ndef main() -> None:\n    global GAP_CLOSE_UM, GAP_REUSE_UM, GAP_MAX_ADDED_FRAC, GAP_MAX_ADDED_ABS, MIN_TRACK_LEN\n    global MOTION_LEARNED_BONUS\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument("--source-dir", type=Path, required=True)\n    parser.add_argument("--data-dir", type=Path, required=True)\n    parser.add_argument("--output-root", type=Path, required=True)\n    parser.add_argument("--arms", default=",".join(ARMS))\n    parser.add_argument("--limit-videos", type=int)\n    parser.add_argument("--gap-close-um", type=float, default=GAP_CLOSE_UM)\n    parser.add_argument("--gap-reuse-um", type=float, default=GAP_REUSE_UM)\n    parser.add_argument("--gap-max-added-frac", type=float, default=GAP_MAX_ADDED_FRAC)\n    parser.add_argument("--gap-max-added-abs", type=int, default=GAP_MAX_ADDED_ABS)\n    parser.add_argument("--min-track-len", type=int, default=MIN_TRACK_LEN)\n    parser.add_argument("--motion-learned-bonus", type=float, default=MOTION_LEARNED_BONUS)\n    parser.add_argument("--disable-dataset-min-track-overrides", action="store_true")\n    args = parser.parse_args()\n    if not math.isfinite(args.gap_close_um) or args.gap_close_um <= 0:\n        raise ValueError("gap-close-um must be finite and positive")\n    if not math.isfinite(args.gap_reuse_um) or args.gap_reuse_um < 0:\n        raise ValueError("gap-reuse-um must be finite and non-negative")\n    if not math.isfinite(args.gap_max_added_frac) or not 0 <= args.gap_max_added_frac <= 1:\n        raise ValueError("gap-max-added-frac must be in [0, 1]")\n    if args.gap_max_added_abs < 0 or args.min_track_len < 1:\n        raise ValueError("gap-max-added-abs must be non-negative and min-track-len positive")\n    if not math.isfinite(args.motion_learned_bonus) or args.motion_learned_bonus < 0:\n        raise ValueError("motion-learned-bonus must be finite and non-negative")\n    GAP_CLOSE_UM = args.gap_close_um\n    GAP_REUSE_UM = args.gap_reuse_um\n    GAP_MAX_ADDED_FRAC = args.gap_max_added_frac\n    GAP_MAX_ADDED_ABS = args.gap_max_added_abs\n    MIN_TRACK_LEN = args.min_track_len\n    MOTION_LEARNED_BONUS = args.motion_learned_bonus\n    if args.disable_dataset_min_track_overrides:\n        MIN_TRACK_LEN_BY_DATASET.clear()\n    arms = tuple(value.strip() for value in args.arms.split(",") if value.strip())\n    unknown = sorted(set(arms) - set(ARMS))\n    if unknown:\n        raise ValueError(f"unknown arms: {unknown}")\n    sources = sorted(args.source_dir.glob("*.geff"))\n    if args.limit_videos is not None:\n        sources = sources[: args.limit_videos]\n    if not sources:\n        raise FileNotFoundError(f"no GEFF graphs under {args.source_dir}")\n    args.output_root.mkdir(parents=True, exist_ok=True)\n    rows: list[dict[str, Any]] = []\n    for index, source in enumerate(sources, start=1):\n        dataset = source.stem\n        source_nodes, source_edges = read_graph(source)\n        for arm in arms:\n            destination = args.output_root / "predictions" / arm / f"{dataset}.geff"\n            resource_guard = (\n                len(source_nodes) > POSTPROCESS_MAX_NODES\n                or len(source_edges) > POSTPROCESS_MAX_EDGES\n            )\n            if resource_guard:\n                copy_graph_fallback(source, destination)\n                nodes, edges = source_nodes, source_edges\n                stats = {\n                    "postprocess_fallback": 1,\n                    "postprocess_fallback_type": "ResourceGuard",\n                }\n                fallback_reason = (\n                    f"graph exceeds safe postprocess size: nodes={len(source_nodes)} "\n                    f"edges={len(source_edges)} limits={POSTPROCESS_MAX_NODES}/"\n                    f"{POSTPROCESS_MAX_EDGES}"\n                )\n                print(\n                    f"[{index}/{len(sources)}] {dataset} {arm} "\n                    f"fallback=ResourceGuard: {fallback_reason}",\n                    flush=True,\n                )\n            else:\n                try:\n                    nodes, edges, stats = apply_arm(\n                        arm, source_nodes, source_edges, dataset, args.data_dir\n                    )\n                    write_graph(destination, nodes, edges)\n                    fallback_reason = ""\n                except Exception as exc:\n                    traceback.print_exc()\n                    copy_graph_fallback(source, destination)\n                    nodes, edges = source_nodes, source_edges\n                    stats = {\n                        "postprocess_fallback": 1,\n                        "postprocess_fallback_type": type(exc).__name__,\n                    }\n                    fallback_reason = str(exc).replace("\\n", " ")[:1000]\n                    print(\n                        f"[{index}/{len(sources)}] {dataset} {arm} "\n                        f"fallback={type(exc).__name__}: {fallback_reason}",\n                        flush=True,\n                    )\n            row = {\n                "dataset": dataset,\n                "arm": arm,\n                "source_nodes": len(source_nodes),\n                "source_edges": len(source_edges),\n                "nodes": len(nodes),\n                "edges": len(edges),\n                "postprocess_fallback_reason": fallback_reason,\n                **stats,\n            }\n            rows.append(row)\n            print(\n                f"[{index}/{len(sources)}] {dataset} {arm} "\n                f"nodes={len(source_nodes)}->{len(nodes)} edges={len(source_edges)}->{len(edges)}",\n                flush=True,\n            )\n    columns = sorted({key for row in rows for key in row})\n    with (args.output_root / "postprocess_stats.csv").open("w", newline="", encoding="utf-8") as handle:\n        writer = csv.DictWriter(handle, fieldnames=columns)\n        writer.writeheader()\n        writer.writerows(rows)\n    manifest = {\n        "source_dir": str(args.source_dir),\n        "data_dir": str(args.data_dir),\n        "videos": len(sources),\n        "arms": list(arms),\n        "voxel_scale_um": VOXEL_SCALE_UM.tolist(),\n        "gap_close_um_per_step": GAP_CLOSE_UM,\n        "gap_endpoint_gate_um": 2.0 * GAP_CLOSE_UM,\n        "gap_reuse_um": GAP_REUSE_UM,\n        "gap_max_added_frac": GAP_MAX_ADDED_FRAC,\n        "gap_max_added_abs": GAP_MAX_ADDED_ABS,\n        "min_track_len": MIN_TRACK_LEN,\n        "dataset_min_track_overrides": dict(MIN_TRACK_LEN_BY_DATASET),\n        "linefit_cap_um": LINEFIT_CAP_UM,\n        "linefit_huber_delta_um": LINEFIT_HUBER_DELTA_UM,\n        "kalman_process_var": KALMAN_PROCESS_VAR,\n        "kalman_measurement_var": KALMAN_MEASUREMENT_VAR,\n        "graph_accel_lambda": GRAPH_ACCEL_LAMBDA,\n        "motion_learned_bonus": MOTION_LEARNED_BONUS,\n        "note": (\n            "motion_relink learned bonuses are available only for edges retained in the source GEFF; "\n            "all other source-target pairs receive probability 0, matching the public notebook post-ILP contract"\n        ),\n    }\n    (args.output_root / "manifest.json").write_text(json.dumps(manifest, indent=2) + "\\n")\n\n\nif __name__ == "__main__":\n    main()\n')
