def sha256(path):
    h=hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda:stream.read(1024*1024),b''):h.update(block)
    return h.hexdigest()

def mount(slug):
    return next((p for p in [INPUT/slug,INPUT/'datasets'/'tatsutaka'/slug] if p.is_dir()),None)

