def launch(command,env,log_path,root):
    log=log_path.open('w')
    process=subprocess.Popen(command,env=env,stdout=log,stderr=subprocess.STDOUT)
    return process,log,root

def wait_owned(processes,label,touch_done=None):
    deadline=time.monotonic()+(42000 if IS_COMPETITION_RERUN else 14400)
    while True:
        states=[p.poll() for p,_,_ in processes]
        failed=[i for i,status in enumerate(states) if status not in (None,0)]
        if not failed and touch_done is not None and all(p.poll()==0 for p,_,_ in processes[:gpu_count]):
            touch_done.touch()
        if failed:
            for i,(p,_,_) in enumerate(processes):
                if states[i] is None:p.terminate()
            for p,log,_ in processes:
                try:p.wait(timeout=30)
                except subprocess.TimeoutExpired:p.kill();p.wait()
                log.close()
            for i in failed:
                err_log = Path(processes[i][1].name)
                if err_log.exists():
                    print(f'=== ERROR LOG ({err_log}) ===\n' + err_log.read_text(errors='replace')[-3000:], flush=True)
            raise RuntimeError(f'{label} worker failure {[(i,states[i],str(processes[i][2])) for i in failed]}')
        if all(status==0 for status in states):break
        if time.monotonic()>deadline:
            for p,_,_ in processes:
                if p.poll() is None:p.terminate()
            raise TimeoutError(f'{label} exceeded timeout')
        time.sleep(2)
    for _,log,_ in processes:log.close()

NUM_WORKERS = CLI_ARGS.workers if CLI_ARGS.workers is not None else (4 if IS_KAGGLE else 1)

def worker_command(shard,root,candidates):
    command=[sys.executable,str(ADDON/'runtime/choice_worker.py'),
             '--addon',str(ADDON),'--model',str(MODEL),'--data',str(DATA_DIR),
             '--out',str(root),'--config',str(CONFIG_PATH),'--shards',str(NUM_WORKERS),'--shard',str(shard),
             '--candidate-source',str(candidates)]
    if MAX_FRAMES is not None:command+=['--max-frames',str(MAX_FRAMES)]
    return command

def run_arm(name,two_models):
    arm=ARM_ROOT/name;arm.mkdir();candidates=arm/'candidates';candidates.mkdir()
    started=time.perf_counter();detectors=[];workers=[]
    capture='capture_ensemble.py' if two_models else 'capture.py'
    use_trt = '1' if IS_TESLA_T4 else '0'
    for shard in range(gpu_count):
        root=arm/f'detector_shard_{shard}';root.mkdir()
        cmd=[sys.executable,str(ADDON/'runtime'/capture),'--model-dir',str(MODEL),
             '--test-dir',str(DATA_DIR),'--output-dir',str(root),
             '--fold','0','--checkpoint','checkpoint_final.pth','--device','cuda',
             '--amp','fp16','--detector-tta-mode','d4-detector',
             '--det-threshold',str(DET_THRESHOLD),'--division-weight','.3',
             '--num-shards',str(gpu_count),'--shard-index',str(shard)]
        if MAX_FRAMES is not None:cmd+=['--max-frames',str(MAX_FRAMES)]
        env=env_base.copy();env.update(CUDA_VISIBLE_DEVICES=str(shard),BIOHUB_ROOT=str(ADDON),
            BIOHUB_DATA_DIR=str(DATA_DIR),BIOHUB_CANDIDATE_DIR=str(candidates),
            BIOHUB_SECOND_MODEL_DIR=str(PRETRAIN_MODEL),BIOHUB_SECOND_MODEL_SHA256=PRETRAIN_SHA,
            BIOHUB_TRT_MODEL_A_SHA256=ACTIVE_DETECTOR_SHA,
            BIOHUB_TRT_ENABLE=use_trt,OMP_NUM_THREADS='1',OPENBLAS_NUM_THREADS='1')
        detectors.append(launch(cmd,env,arm/f'detector_{shard}.log',root))
    if not IS_KAGGLE:
        # On a single local GPU (e.g. 8GB VRAM), complete full-volume 3D nnU-Net detection before launching division workers.
        wait_owned(detectors, name + '_detectors')
        (arm/'detectors_done').touch()
        detectors = []
    for shard in range(NUM_WORKERS):
        root=arm/f'shard_{shard}'
        env=env_base.copy();env.update(CUDA_VISIBLE_DEVICES=str(shard%gpu_count),
            BIOHUB_TRT_ENABLE='0',BIOHUB_DIVISION_TRT_ENABLE=use_trt,
            BIOHUB_DIVISION_TRT_ENGINE_DIR=str(DIVISION_ENGINES),
            BIOHUB_DIVISION_TRT_RECEIPT_DIR=str(root/'division_trt'),
            BIOHUB_PAIR_FOLD_MODE='fold',
            BIOHUB_DYNAMIC_SCHEDULING='1',BIOHUB_DYNAMIC_CLAIMS=str(arm/'claims'),
            BIOHUB_DETECTORS_DONE=str(arm/'detectors_done'),BIOHUB_WORKER_SHARD=str(shard))
        workers.append(launch(worker_command(shard,root,candidates),env,
                              arm/f'worker_{shard}.log',root))
    wait_owned(detectors+workers,name,touch_done=(arm/'detectors_done') if detectors else None)
    assert {p.stem for p in candidates.glob('*.pkl')}==set(run_stems)
    graphs=arm/'final_graphs';graphs.mkdir()
    receipts=[]
    for _,_,root in workers:
        receipt=json.loads((root/'worker_receipt.json').read_text());assert receipt['passed']
        receipts.append(receipt)
        for source in (root/'final_graphs').glob('*.geff'):
            target=graphs/source.name;assert not target.exists()
            shutil.copytree(source,target)
    assigned=[stem for receipt in receipts for stem in receipt['stems']]
    assert len(assigned)==len(set(assigned))==len(run_stems) and set(assigned)==set(run_stems)
    assert {p.stem for p in graphs.glob('*.geff')}==set(run_stems)
    return dict(name=name,two_models=two_models,detector_variant=CLI_ARGS.detector,det_threshold=DET_THRESHOLD,
                worker_wall_seconds=time.perf_counter()-started,
                worker_receipts=receipts,graphs_dir=str(graphs),candidate_dir=str(candidates),
                detector_log_paths=[str(arm/f'detector_{s}.log') for s in range(gpu_count)])

