DERIVED_PARENT_NOTEBOOK_SHA256='dd0516c94bf3743536b7531fa28e81c8dd13ea8a734f0d0227eb07ba02b04914'
PARENT_SOURCE_HASH='b79c69304e0471fd10ad5027aa3667965e654b7a8a1a482559b5d94647b7e37f'
comparison=dict(run_marker=RUN_MARKER,parent_source_notebook_sha256=PARENT_SOURCE_HASH,
    is_competition_rerun=IS_COMPETITION_RERUN,stems=run_stems,max_frames=MAX_FRAMES,
    detector_motion_sha256=ACTIVE_DETECTOR_SHA,arms=[])
for arm in (ensemble,):
    root=ARM_ROOT/arm['name'];submission=root/'submission.csv'
    diagnostics=root/'submission.diagnostics.json';started=time.perf_counter()
    subprocess.run([sys.executable,str(TOOLS/'biohub_geff_to_submission.py'),
        '--graphs-dir',arm['graphs_dir'],'--test-dir',str(DATA_DIR),
        '--sample-submission',str(SAMPLE),'--output-csv',str(submission),
        '--diagnostics-json',str(diagnostics)],env=env_base,check=True)
    arm['csv_seconds']=time.perf_counter()-started
    arm['rows']=sum(1 for _ in submission.open())
